      {:sel, "CASE time WHEN '2023-11-14T22:13:20Z' THEN 'a' END",
       "a CASE comparing time with text: the engine reads the text as a timestamp, which is not modelled"},
      {:raw, "SELECT avg(coalesce(host, x)) AS r FROM main WHERE false",
       "COALESCE of a float with text: the engine casts the text to the number when it runs the plan (and closes the connection when a value does not cast), which is not modelled"},
