      {:raw, "SELECT CASE WHEN b THEN i WHEN b THEN f ELSE u END AS r FROM mext ORDER BY time",
       "a CASE whose results are an unsigned integer beside another number: the engine's common type for them is not modelled"},
      {:raw, "SELECT first_value(1e3 ORDER BY time) AS r FROM main",
