      {:raw, "SELECT count(distinct 'x y'), max(n) FROM main WHERE n > 100",
       "a DISTINCT aggregate of a literal beside another aggregate over no row: the engine's answer for it is not modelled"},
      {:raw, "SELECT count(distinct 'a'), max(n) FROM main WHERE false",
       "a DISTINCT aggregate of a literal beside another aggregate over no row: the engine's answer for it is not modelled"},
      {:raw, "SELECT sum(distinct 1), max(n) FROM main WHERE n > 100",
       "a DISTINCT aggregate of a literal beside another aggregate over no row: the engine's answer for it is not modelled"},
      {:raw, "SELECT count(distinct true), max(n) FROM main WHERE n > 100",
       "a DISTINCT aggregate of a literal beside another aggregate over no row: the engine's answer for it is not modelled"},
      {:raw, "SELECT count(distinct 1.5), max(n) FROM main WHERE n > 100",
       "a DISTINCT aggregate of a literal beside another aggregate over no row: the engine's answer for it is not modelled"},
      {:raw, "SELECT coalesce(i, f, u) AS r FROM mext ORDER BY time",
